import json

with open('output/solution.json') as f:
    data = json.load(f)

events = data['events']

print(f"Total events: {len(events)}\n")

# Check each game
for game_num in range(1, 11):
    game_events = [e for e in events if e['game'] == game_num]
    print(f"Game {game_num}: {len(game_events)} events")

print(f"\n--- Sample from Game 5 ---")
game5 = [e for e in events if e['game'] == 5][:3]
for e in game5:
    print(f"  {e['attacker']} attacking: {e['hit_count']} hits, {e['damage_band']}, {e['terminal']}")

print(f"\n--- Sample from Game 10 ---")
game10 = [e for e in events if e['game'] == 10][:3]
for e in game10:
    print(f"  {e['attacker']} attacking: {e['hit_count']} hits, {e['damage_band']}, {e['terminal']}")

# Verify all required fields present
print(f"\n--- Field validation ---")
required_fields = ['game', 'attacker', 'victim_stock_before', 'hit_count', 'damage_band', 'terminal']
all_valid = True
for i, event in enumerate(events[:10]):  # Check first 10
    for field in required_fields:
        if field not in event:
            print(f"Event {i} missing field: {field}")
            all_valid = False

if all_valid:
    print("All checked events have required fields ✓")

# Check filtering criteria
print(f"\n--- Filtering validation ---")
violations = []
for i, e in enumerate(events):
    if e['hit_count'] < 4 and e['terminal'] != 'kill':
        violations.append(i)

if len(violations) == 0:
    print("All events meet criteria (hit_count >= 4 OR terminal == 'kill') ✓")
else:
    print(f"Found {len(violations)} events violating criteria")

# Check value ranges
print(f"\n--- Value validation ---")
valid_attackers = {'P1', 'P2'}
valid_damage_bands = {'light', 'heavy', 'devastating'}
valid_terminals = {'kill', 'escape', 'reversal'}

invalid = []
for i, e in enumerate(events):
    if e['attacker'] not in valid_attackers:
        invalid.append((i, 'attacker', e['attacker']))
    if e['damage_band'] not in valid_damage_bands:
        invalid.append((i, 'damage_band', e['damage_band']))
    if e['terminal'] not in valid_terminals:
        invalid.append((i, 'terminal', e['terminal']))
    if not (1 <= e['game'] <= 10):
        invalid.append((i, 'game', e['game']))

if len(invalid) == 0:
    print("All values are valid ✓")
else:
    for idx, field, value in invalid[:5]:
        print(f"Event {idx} has invalid {field}: {value}")

